//! Raw bindings to ExcellentPDF's C shim around SumatraPDF's MuPDF 1.28.5 tree (plan §6.1, §6.3, ADR 0004).
//!
//! Only the `ex_*` functions of `csrc/shim.h` are exposed. Each runs its MuPDF calls inside `fz_try` / `fz_catch`,
//! so no `longjmp` crosses a Rust frame; failures come back as an `FZ_ERROR_*` code and an [`ex_error`]. MuPDF's own
//! types are opaque here. Use the safe `excellent-mupdf` crate instead of calling these directly.
//!
//! `build.rs` compiles MuPDF and its libraries with the `cc` crate. `src/bindings.rs` is generated by bindgen and
//! committed; regenerate it with `cargo build -p excellent-mupdf-sys --features regenerate-bindings`.

#![no_std]

mod opaque;

#[rustfmt::skip]
#[allow(
    non_camel_case_types,
    non_snake_case,
    non_upper_case_globals,
    missing_docs,
    unreachable_pub,
    clippy::all,
    reason = "generated by bindgen from csrc/shim.h"
)]
mod bindings;

pub use bindings::*;
pub use opaque::*;
